-- KADE Caminhões: banco de DEMONSTRAÇÃO (estrutura atual + dados fictícios).
-- Gerado por demo/gerar_demo.php. Não edite à mão: rode o gerador de novo.
--
-- Carregue num banco à parte ou no banco local (as tabelas dele são APAGADAS):
--   mysql -u root --default-character-set=utf8mb4 NOME_DO_BANCO < demo/kade_demo.sql
--
-- Logins: admin / Teste@123 (administrador), clienteteste / Teste@123 (cliente dos testes
-- automáticos) e os assinantes fictícios com a senha Demo@123 (ex.: rotasul). As datas são relativas
-- ao momento da carga: recarregue antes de cada demonstração.

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `account`;
CREATE TABLE `account` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `date_hr_proc` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `status` enum('PAID','UNPAID','CANCEL') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UNPAID',
  `client_user_person_id` bigint unsigned NOT NULL,
  `validate_month` int NOT NULL DEFAULT '12',
  PRIMARY KEY (`id`),
  KEY `fk_account_client1` (`client_user_person_id`),
  CONSTRAINT `fk_account_client1` FOREIGN KEY (`client_user_person_id`) REFERENCES `client` (`user_person_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `address`;
CREATE TABLE `address` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `cep` int unsigned NOT NULL,
  `street` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `number` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `complement` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `neighborhood` varchar(72) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `city` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `state` char(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `state_nm` varchar(72) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_cep` (`cep`),
  KEY `idx_city` (`city`),
  KEY `idx_state` (`state`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `cep_cache`;
CREATE TABLE `cep_cache` (
  `cep` char(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `street` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `neighborhood` varchar(72) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `city` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `state` char(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`cep`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `client`;
CREATE TABLE `client` (
  `user_person_id` bigint unsigned NOT NULL,
  PRIMARY KEY (`user_person_id`),
  CONSTRAINT `fk_client_person1` FOREIGN KEY (`user_person_id`) REFERENCES `person` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `employee`;
CREATE TABLE `employee` (
  `user_login` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`user_login`),
  CONSTRAINT `fk_employee_user1` FOREIGN KEY (`user_login`) REFERENCES `user` (`login`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `idx_traveling_city`;
CREATE TABLE `idx_traveling_city` (
  `state` char(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `city` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `state_nm` varchar(72) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `qty_real` bigint unsigned NOT NULL DEFAULT '1',
  `qty_illus` bigint unsigned NOT NULL DEFAULT '1',
  PRIMARY KEY (`state`,`city`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `installment`;
CREATE TABLE `installment` (
  `account_id` bigint unsigned NOT NULL,
  `id` int unsigned NOT NULL DEFAULT '1',
  `value` float NOT NULL DEFAULT '0',
  `payment_value` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0',
  `due_date` date NOT NULL,
  `payment_date` date DEFAULT NULL,
  `status` enum('PAID','UNPAID','CANCEL') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UNPAID',
  `payment_method_id` int unsigned DEFAULT NULL,
  PRIMARY KEY (`id`,`account_id`),
  KEY `fk_installment_payment_method1_idx` (`payment_method_id`),
  KEY `fk_installment_account1` (`account_id`),
  CONSTRAINT `fk_installment_account1` FOREIGN KEY (`account_id`) REFERENCES `account` (`id`),
  CONSTRAINT `fk_installment_payment_method1` FOREIGN KEY (`payment_method_id`) REFERENCES `payment_method` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `link_confirm`;
CREATE TABLE `link_confirm` (
  `user_person_id` bigint unsigned NOT NULL,
  `hash` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`user_person_id`),
  UNIQUE KEY `hash_UNIQUE` (`hash`),
  CONSTRAINT `fk_link_confirm_person1` FOREIGN KEY (`user_person_id`) REFERENCES `person` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `log_sms`;
CREATE TABLE `log_sms` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `channel` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SMS',
  `msg_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `from` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `body` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `ip_trat` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `url_request` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `type_log` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `log` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `date_hr` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_log_sms_msg` (`channel`,`msg_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `login_attempt`;
CREATE TABLE `login_attempt` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `login` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `ip` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_login_attempt_login` (`login`,`created_at`),
  KEY `idx_login_attempt_created` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `messenger_contact`;
CREATE TABLE `messenger_contact` (
  `channel` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `external_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`channel`,`external_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `payment_method`;
CREATE TABLE `payment_method` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `descr` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `enabled` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `person`;
CREATE TABLE `person` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `type` enum('PF','PJ','NO') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NO',
  `address_id` bigint unsigned DEFAULT NULL,
  `phone_id` bigint NOT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_person_phone1_idx` (`phone_id`),
  KEY `fk_person_address1` (`address_id`),
  CONSTRAINT `fk_person_address1` FOREIGN KEY (`address_id`) REFERENCES `address` (`id`),
  CONSTRAINT `fk_person_phone1` FOREIGN KEY (`phone_id`) REFERENCES `phone` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `person_entity`;
CREATE TABLE `person_entity` (
  `person_id` bigint unsigned NOT NULL,
  `cnpj` char(14) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `ie` varchar(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `contact` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`person_id`),
  UNIQUE KEY `cnpj_UNIQUE` (`cnpj`),
  CONSTRAINT `fk_person_entity_person1` FOREIGN KEY (`person_id`) REFERENCES `person` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `person_individual`;
CREATE TABLE `person_individual` (
  `person_id` bigint unsigned NOT NULL,
  `cpf` char(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `gender` enum('MASCULINO','FEMININO') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dateBirth` date DEFAULT NULL,
  PRIMARY KEY (`person_id`),
  UNIQUE KEY `cpf_UNIQUE` (`cpf`),
  CONSTRAINT `fk_person_individual_person` FOREIGN KEY (`person_id`) REFERENCES `person` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `phone`;
CREATE TABLE `phone` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `phone` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `ddd` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `ddi` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_phone` (`ddi`,`ddd`,`phone`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `profile`;
CREATE TABLE `profile` (
  `id` char(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `descr` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `enabled` tinyint(1) NOT NULL DEFAULT '1',
  `super` tinyint(1) NOT NULL DEFAULT '0',
  `intern` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `user`;
CREATE TABLE `user` (
  `login` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `person_id` bigint unsigned NOT NULL,
  `password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('PEND','CHEK','BLCK','CANC') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PEND',
  `text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `date_cad` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `dt_hr_alt` timestamp NULL DEFAULT NULL,
  `user_alt_login` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`login`),
  UNIQUE KEY `login_UNIQUE` (`login`),
  KEY `fk_user_user1_idx` (`user_alt_login`),
  KEY `fk_users_person1` (`person_id`),
  CONSTRAINT `fk_user_user1` FOREIGN KEY (`user_alt_login`) REFERENCES `user` (`login`),
  CONSTRAINT `fk_users_person1` FOREIGN KEY (`person_id`) REFERENCES `person` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `user_profile`;
CREATE TABLE `user_profile` (
  `user_person_id` bigint unsigned NOT NULL,
  `profile_id` char(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `enabled` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`user_person_id`,`profile_id`),
  KEY `fk_user_profile_profile1` (`profile_id`),
  KEY `fk_user_profile_person1` (`user_person_id`),
  CONSTRAINT `fk_user_profile_person1` FOREIGN KEY (`user_person_id`) REFERENCES `person` (`id`),
  CONSTRAINT `fk_user_profile_profile1` FOREIGN KEY (`profile_id`) REFERENCES `profile` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `vehicle_contact`;
CREATE TABLE `vehicle_contact` (
  `vehicle_traveling_id` bigint unsigned NOT NULL,
  `person_id` bigint unsigned NOT NULL,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `phone_contact_id` bigint NOT NULL,
  PRIMARY KEY (`vehicle_traveling_id`),
  KEY `fk_vehicle_contact_phone1_idx` (`phone_contact_id`),
  KEY `fk_vehicle_contact_vehicle_traveling1` (`vehicle_traveling_id`),
  KEY `fk_vehicle_contact_person1` (`person_id`),
  CONSTRAINT `fk_vehicle_contact_person1` FOREIGN KEY (`person_id`) REFERENCES `person` (`id`),
  CONSTRAINT `fk_vehicle_contact_phone1` FOREIGN KEY (`phone_contact_id`) REFERENCES `phone` (`id`),
  CONSTRAINT `fk_vehicle_contact_vehicle_traveling1` FOREIGN KEY (`vehicle_traveling_id`) REFERENCES `vehicle_traveling` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `vehicle_traveling`;
CREATE TABLE `vehicle_traveling` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `vehicle_type_id` int unsigned NOT NULL,
  `date_hr_proc` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `source` enum('WEB','SMS','WHATSAPP','TELEGRAM') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'WEB',
  `address_id` bigint unsigned NOT NULL,
  `ip` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('ONLY_VIEW','UTILIZED','NONE','CANCEL','EXPIRED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NONE',
  `user_person_id_ut` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_qmain` (`date_hr_proc`,`status`),
  KEY `fk_vehicle_traveling_address1` (`address_id`),
  KEY `FK_vehicle_traveling_type` (`vehicle_type_id`),
  KEY `fk_vehicle_traveling_person_ut` (`user_person_id_ut`),
  CONSTRAINT `fk_vehicle_traveling_address1` FOREIGN KEY (`address_id`) REFERENCES `address` (`id`),
  CONSTRAINT `fk_vehicle_traveling_person_ut` FOREIGN KEY (`user_person_id_ut`) REFERENCES `person` (`id`),
  CONSTRAINT `FK_vehicle_traveling_type` FOREIGN KEY (`vehicle_type_id`) REFERENCES `vehicle_type` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci PACK_KEYS=1;

DROP TABLE IF EXISTS `vehicle_traveling_user`;
CREATE TABLE `vehicle_traveling_user` (
  `vehicle_traveling_id` bigint unsigned NOT NULL,
  `user_person_id` bigint unsigned NOT NULL,
  `date_hr_used` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `status` enum('ONLY_VIEW','UTILIZED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ONLY_VIEW',
  PRIMARY KEY (`vehicle_traveling_id`,`user_person_id`,`date_hr_used`),
  KEY `fk_vehicle_traveling_has_users_vehicle_traveling1` (`vehicle_traveling_id`),
  KEY `fk_vehicle_traveling_user_person1` (`user_person_id`),
  CONSTRAINT `fk_vehicle_traveling_has_users_vehicle_traveling1` FOREIGN KEY (`vehicle_traveling_id`) REFERENCES `vehicle_traveling` (`id`),
  CONSTRAINT `fk_vehicle_traveling_user_person1` FOREIGN KEY (`user_person_id`) REFERENCES `person` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `vehicle_type`;
CREATE TABLE `vehicle_type` (
  `id` int unsigned NOT NULL,
  `descr` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `enabled` tinyint(1) DEFAULT '1',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DELIMITER ;;
DROP PROCEDURE IF EXISTS `add_idx_traveling_city`;;
CREATE PROCEDURE `add_idx_traveling_city`(p_address_id BIGINT)
BEGIN
	DECLARE ld_state CHAR(2) DEFAULT NULL;
	DECLARE ld_state_nm VARCHAR(72);
	DECLARE ld_city VARCHAR(60);
	DECLARE CONTINUE HANDLER FOR NOT FOUND BEGIN END;

	SELECT state, state_nm, city INTO ld_state, ld_state_nm, ld_city
	  FROM address WHERE id = p_address_id;

	IF (ld_state IS NOT NULL AND ld_state != '') THEN
		INSERT INTO idx_traveling_city (state, city, state_nm, qty_real, qty_illus)
		VALUES (ld_state, ld_city, ld_state_nm, 1, 1)
		ON DUPLICATE KEY UPDATE qty_real = qty_real + 1, qty_illus = qty_illus + 1;
	END IF;
END;;
DROP PROCEDURE IF EXISTS `remove_idx_traveling_city`;;
CREATE PROCEDURE `remove_idx_traveling_city`(p_address_id BIGINT)
BEGIN
	DECLARE ld_state CHAR(2) DEFAULT NULL;
	DECLARE ld_city VARCHAR(60);
	DECLARE CONTINUE HANDLER FOR NOT FOUND BEGIN END;

	SELECT state, city INTO ld_state, ld_city
	  FROM address WHERE id = p_address_id;

	IF (ld_state IS NOT NULL AND ld_state != '') THEN
		-- Nunca abaixo de zero (as colunas s├úo UNSIGNED)
		UPDATE idx_traveling_city
		   SET qty_real  = GREATEST(CAST(qty_real AS SIGNED) - 1, 0)
		     , qty_illus = GREATEST(CAST(qty_illus AS SIGNED) - 1, 0)
		 WHERE state = ld_state AND city = ld_city;
	END IF;
END;;
CREATE TRIGGER `ao_inserir` AFTER INSERT ON `vehicle_traveling` FOR EACH ROW BEGIN
	IF (NEW.status IN ('NONE', 'ONLY_VIEW')) THEN
		CALL add_idx_traveling_city(NEW.address_id);
	END IF;
END;;
CREATE TRIGGER `ao_atualizar` AFTER UPDATE ON `vehicle_traveling` FOR EACH ROW BEGIN
	DECLARE was_active BOOLEAN DEFAULT (OLD.status IN ('NONE', 'ONLY_VIEW'));
	DECLARE is_active BOOLEAN DEFAULT (NEW.status IN ('NONE', 'ONLY_VIEW'));

	IF (was_active AND NOT is_active) THEN
		CALL remove_idx_traveling_city(OLD.address_id);
	ELSEIF (is_active AND NOT was_active) THEN
		CALL add_idx_traveling_city(NEW.address_id);
	END IF;
END;;
DELIMITER ;

